import { appScopedResourceLabel, expr, sanitizeName, scopedResourceLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { SERVICE_ACCOUNT_ACCESS_POLICY_RESOURCE_TYPE, SERVICE_ACCOUNT_RESOURCE_TYPE } from "./module.js";
/**
 * Resolve a `serviceAccountRef({ app, name })` token to its terraform value:
 * `elementum_service_account.<label>.id` when the name matches an account
 * authored on the SAME app's `serviceAccounts` bag, otherwise a foreign
 * `data.elementum_service_account` lookup (name/app_id-scoped, matching the
 * provider's data source). Cross-app references are rejected with a
 * diagnostic rather than silently guessed at — same restriction skill tool
 * `runAs` already applies (a service account has no email to disambiguate
 * it, only its owning app + name).
 */
export function serviceAccountRefToTf(token, opts, where, diagnostics) {
    if (token.__kind !== "serviceAccount" || token.name === undefined || token.name === "") {
        diagnostics.push(`${where}: serviceAccount must be a serviceAccountRef({ app, name }); dropped`);
        return undefined;
    }
    if (token.appRefName !== opts.appRefName) {
        diagnostics.push(`${where}: service account ${JSON.stringify(token.name)} belongs to app ${JSON.stringify(token.appRefName ?? "")}, not owning app ${JSON.stringify(opts.appRefName)}; dropped`);
        return undefined;
    }
    const local = Object.entries(opts.serviceAccounts ?? {}).filter(([, account]) => `${account.firstName} ${account.lastName}`.trim() === token.name);
    if (local.length > 1) {
        diagnostics.push(`${where}: service account name ${JSON.stringify(token.name)} is ambiguous in app ${JSON.stringify(opts.appRefName)}; dropped`);
        return undefined;
    }
    if (local.length === 1) {
        return expr.resourceAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, appScopedResourceLabel(opts.appTfLabel, tsLabelToTfLabel(local[0][0])), ["id"]);
    }
    // A pulled foreign reference can lack an owning app id when the exporter
    // could not resolve that app. Do not emit an invalid data source block with
    // a missing required app_id; callers treat an undefined lookup as absent.
    if (opts.appId === undefined) {
        diagnostics.push(`${where}: service account ${JSON.stringify(token.name)} has no resolvable owning app id; dropped`);
        return undefined;
    }
    const label = appScopedResourceLabel(opts.appTfLabel, sanitizeName(token.name));
    opts.orgRefs.rawLookup(SERVICE_ACCOUNT_RESOURCE_TYPE, label, token.name, { app_id: opts.appId });
    return expr.dataAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, label, ["id"]);
}
function principalValues(values, type, where, orgRefs, diagnostics) {
    if (values === undefined || values.length === 0)
        return undefined;
    const out = [];
    for (const value of values) {
        if (type === "elementum_user" && value.__kind === "user") {
            const email = value.email;
            const label = sanitizeName(email.split("@", 1)[0] ?? email);
            orgRefs.rawLookup(type, label, email);
            out.push(expr.dataAttr(type, label, ["id"]));
            continue;
        }
        if (type === "elementum_group" && value.__kind === "group") {
            const refName = value.refName ?? "";
            const resolved = orgRefs.byTsLabel("groups", refName);
            if (resolved === undefined)
                diagnostics.push(`${where}: group ${JSON.stringify(refName)} is not in org.ts; dropped`);
            else
                out.push(expr.dataAttr(type, resolved.tfLabel, ["id"]));
            continue;
        }
        diagnostics.push(`${where}: expected a typed ${type === "elementum_user" ? "userRef" : "group ref"}; dropped`);
    }
    return out.length > 0 ? out : undefined;
}
function roleValue(value, roles, ownerTfLabel, appId, orgRefs) {
    const local = Object.entries(roles ?? {}).find(([, role]) => role.name === value.name);
    if (local !== undefined) {
        return expr.resourceAttr("elementum_role", scopedResourceLabel(ownerTfLabel, tsLabelToTfLabel(local[0]), "app"), ["id"]);
    }
    const label = sanitizeName(value.name);
    orgRefs.rawLookup("elementum_role", label, value.name, { object_id: appId });
    return expr.dataAttr("elementum_role", label, ["id"]);
}
export function serviceAccountsToTf(accounts, opts) {
    const blocks = [];
    for (const [key, account] of Object.entries(accounts ?? {})) {
        const label = scopedResourceLabel(opts.ownerTfLabel, tsLabelToTfLabel(key), "app");
        const attrs = {
            app_id: opts.appId,
            first_name: account.firstName,
            last_name: account.lastName,
            purpose: account.purpose,
        };
        if (account.status !== undefined)
            attrs["status"] = account.status;
        if (account.roles !== undefined)
            attrs["role_ids"] = account.roles.map((role) => roleValue(role, opts.roles, opts.ownerTfLabel, opts.appId, opts.orgRefs));
        blocks.push({ kind: "resource", type: SERVICE_ACCOUNT_RESOURCE_TYPE, label, attrs });
        for (const [index, policy] of (account.accessPolicies ?? []).entries()) {
            const policyAttrs = {
                app_id: opts.appId,
                service_account_id: expr.resourceAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, label, ["id"]),
            };
            const users = principalValues(policy.users, "elementum_user", `serviceAccounts.${key}.accessPolicies[${index}].users`, opts.orgRefs, opts.diagnostics);
            const groups = principalValues(policy.groups, "elementum_group", `serviceAccounts.${key}.accessPolicies[${index}].groups`, opts.orgRefs, opts.diagnostics);
            if (users !== undefined)
                policyAttrs["user_ids"] = users;
            if (groups !== undefined)
                policyAttrs["group_ids"] = groups;
            blocks.push({
                kind: "resource",
                type: SERVICE_ACCOUNT_ACCESS_POLICY_RESOURCE_TYPE,
                label: `${label}_access_policy${index === 0 ? "" : `_${index}`}`,
                attrs: policyAttrs,
            });
        }
    }
    return blocks;
}
